attachments.value:
{%- set existing_groups = dashboard["dashboard_groups"] -%}
{%- set existing_pages = dashboard["dashboard_pages"] | map(attribute="name") | list -%}
{%- set ns = namespace(d_pages_dict={}, d_groups_dict={}) -%}
{%- set customer_tag = customerTag -%}

{%- set dlist = engine.query_stream_data(
    stream="rda_packs_dynamic_groups_and_pages",
    cfxql_query="customer_tag is empty and dashboard_group_label is not 'Multi Network Discovery' and dashboard_app_name is 'NetworkNode'"
) or [] -%}

{%- if dlist -%}
    {%- for i in dlist -%}
        {%- set page_name = i["dashboard_page_name"] -%}
        {%- if "topology_drill_down_for_alerts_and_incidents" in page_name -%}
            {%- if i["dashboard_group_name"] not in ns.d_groups_dict -%}
                {%- set _ = ns.d_groups_dict.update({ i["dashboard_group_name"]: {
                    "g_name": i["dashboard_group_name"],
                    "g_label": i["dashboard_group_label"],
                    "g_icon": i["dashboard_group_icon"]
                }}) -%}
            {%- endif -%}
            {%- if i["dashboard_page_name"] not in existing_pages and i["dashboard_page_name"] not in ns.d_pages_dict -%}
                {%- set _ = ns.d_pages_dict.update({ i["dashboard_page_name"]: {
                    "name": i["dashboard_page_name"],
                    "label": i["dashboard_page_label"],
                    "icon": i["dashboard_page_icon"],
                    "group": i["dashboard_page_group"]
                }}) -%}
            {%- endif -%}
        {%- endif -%}
    {%- endfor -%}

    {%- for group in ns.d_groups_dict.values() -%}
        {%- if group.g_name not in existing_groups | map(attribute='g_name') | list -%}
            {%- set _ = dashboard["dashboard_groups"].update({
                group.g_name: { "icon": group.g_icon, "label": group.g_label }
            }) -%}
        {%- endif -%}
    {%- endfor -%}

    {%- for page in ns.d_pages_dict.values() -%}
        {%- set _ = dashboard["dashboard_pages"].append({
            "name": page.name, "label": page.label, "icon": page.icon, "group": page.group
        }) -%}
    {%- endfor -%}
{%- endif -%}
